// Bloons TD Battles 2 verisi: scripts/btd-classic-data.ps1 -Game BTDB2 ile oluşturulur, elle düzenlenmez.
const REHBER = {"game":"Bloons TD Battles 2","intro":["İki oyuncunun karşı karşıya oynadığı BTD: kendi balonlarını patlatırken rakibine balon gönderirsin. Kuleler BTD6\u0027daki gibi 3 yol × 5 seviye; fiyatlar savaş modundaki fiyatlardır.","Head-to-head BTD: pop your own bloons while sending bloons to your opponent. Towers have 3 paths × 5 tiers like BTD6; costs are battle-mode costs."],"sections":[{"id":"kuleler","title":["Kuleler ve yükseltmeler","Towers and upgrades"],"noun":["kule","towers"],"badge":["Yükseltme yolları · Fiyatlar","Upgrade paths · Costs"],"text":["{n} kule: her yükseltmenin adı, fiyatı ve ne yaptığı.","{n} towers: every upgrade with its cost and effect."],"image":"portrait","items":[{"id":"alchemist","name":"Alchemist","quote":"Harnessing powers of science and magic, splashes Bloons with acid, also brews various potions with different effects.","stats":[[["Fiyat","Cost"],"$550"],[["Hasar","Damage"],"1 (attack potion and acid pools) / 1 / 2.0s for 4.0s (corrosion DoT)"],[["Delme","Pierce"],"12"],[["Saldırı hızı","Attack speed"],"1.8s"],[["Menzil","Range"],"45"],[["Kamuflaj","Camo"],"No"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Larger Potions [[d|$250]]: Larger potions splash in a larger area.","[[k|2]] Acidic Mixture Dip [[d|$350]]: Throws a potion at nearby Monkeys that allows them to pop Leads and do extra damage to Ceramic and MOAB-Class Bloons until it wears off.","[[k|3]] Berserker Brew [[d|$1.650]]: Special brew gives Monkeys extra damage, range and attack speed. Lasts longer.","[[k|4]] Stronger Stimulant [[d|$2.800]]: Extra strong berserker brew has even more powerful effect on the target. Lasts even longer.","[[k|5]] Permanent Brew [[d|$55.000]]: Berserker brew becomes PERMANENT on Monkeys who drink it."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Stronger Acid [[d|$250]]: Acid potions dissolve Bloons faster.","[[k|2]] Perishing Potions [[d|$475]]: Attack potions deal more damage to MOAB-class Bloons and strip Fortified off smaller Bloons. Also strengthens Brews and Stimulants.","[[k|3]] Unstable Concoction [[d|$4.000]]: Coats MOAB bloons in an explosive substance that causes a large explosion when they are popped.","[[k|4]] Transforming Tonic [[d|$4.500]]: Transformation ability: turns Alchemist into powerful attack Monster for 20 seconds.","[[k|5]] Total Transformation [[d|$45.000]]: Transforms five Monkeys nearby into crazy attack monsters for 17.5 seconds."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Faster Throwing [[d|$550]]: Throws potions and attacks faster.","[[k|2]] Acid Pool [[d|$450]]: If no Bloons are nearby Alchemist can drench nearby track with acid.","[[k|3]] Lead To Gold [[d|$1.000]]: Converts Lead Bloons to GOLD! Special solvents do extra damage to Lead Bloons, destroying them in one shot and generating cash.","[[k|4]] Rubber to Gold [[d|$2.500]]: Converts all Bloons partially into gold, giving you cash for each pop from affected bloons.","[[k|5]] Bloon Master Alchemist [[d|$40.000]]: Secret shrink potion converts all affected Bloons to Red Bloons."]}],"image":"https://static.wikia.nocookie.net/b__/images/e/ea/000-Alchemist.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"banana-farm","name":"Banana Farm","quote":"Generates bananas each round that convert into game money to spend on more stuff.","stats":[[["Fiyat","Cost"],"$1.000"],[["Menzil","Range"],"40"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Increased Production [[d|$550]]: Grows 2 extra Banana bunches per round.","[[k|2]] Greater Production [[d|$550]]: Grows 2 MORE extra Banana bunches per round.","[[k|3]] Banana Plantation [[d|$2.750]]: Grows 16 banana bunches per round.","[[k|4]] Banana Research Facility [[d|$16.000]]: Produces 5 large Banana crates every round worth $600 each.","[[k|5]] Banana Central [[d|$66.000]]: You want banana? We have banana!"]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Long Life Bananas [[d|$200]]: Bananas last 30 seconds before rotting instead of 15.","[[k|2]] Valuable Bananas [[d|$700]]: Bananas are worth 25% more cash per bunch.","[[k|3]] Monkey Bank [[d|$4.600]]: All money generated by this farm is now stored in the bank and earns 20% interest every round.","[[k|4]] IMF Loan [[d|$8.000]]: IMF Loan ability: Gives you $20,000 but you have to pay it back over time.","[[k|5]] Monkey-Nomics [[d|$45.000]]: For when you\u0027re too big to fail..."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Quality Soil [[d|$400]]: Nutrient rich soil makes this farm\u0027s top and middle path upgrades 20% cheaper.","[[k|2]] Banana Salvage [[d|$240]]: Uncollected Bananas auto-collect for almost their full amount, and Banks autocollect when full. Farm can be sold for 10% more value.","[[k|3]] Marketplace [[d|$2.800]]: Generates money each round and adds it to your total. No fuss.","[[k|4]] Central Market [[d|$13.000]]: Earns heaps of money each round and gives Merchantmen +10% income.","[[k|5]] Monkey Wall Street [[d|$46.000]]: Hub of Monkey trades earns colossal income each round."]}],"image":"https://static.wikia.nocookie.net/b__/images/c/cb/000-BananaFarm.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"bomb-shooter","name":"Bomb Shooter","quote":"Launches a powerful bomb at the Bloons. Slow rate of fire but affects a radius around the explosion.","stats":[[["Fiyat","Cost"],"$525"],[["Hasar","Damage"],"1"],[["Delme","Pierce"],"14"],[["Saldırı hızı","Attack speed"],"Moderately Slow (every 1.5s)"],[["Menzil","Range"],"40"],[["Kamuflaj","Camo"],"Limited (x-x-5 passive)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Bigger Bombs [[d|$350]]: Shoots larger bombs, they have a larger blast area and more popping power.","[[k|2]] Heavy Bombs [[d|$650]]: Heavy duty bombs can smash through 2 layers of Bloon at once and pop more Bloons.","[[k|3]] Really Big Bombs [[d|$1.200]]: Huge bombs deal greater damage in a large area and allow Frags to pop more Bloons.","[[k|4]] Bloon Impact [[d|$3.600]]: Explosions become so violent Bloons are stunned for a short time when they are hit. Range is increased and frags are even more effective.","[[k|5]] Bloon Crush [[d|$55.000]]: Bloon shattering explosions do massive damage and can stun MOAB class Bloons."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Faster Reload [[d|$250]]: Reloads faster.","[[k|2]] Missile Launcher [[d|$400]]: Exchanges bombs for missiles, which fire faster, fly faster, and increase range.","[[k|3]] MOAB Mauler [[d|$900]]: MOAB Maulers do much more damage to MOAB class Bloons.","[[k|4]] MOAB Assassin [[d|$3.200]]: Assassinate MOAB ability: Special missile does massive damage to MOAB-class Bloons. Attack range and MOAB-class damage also increased.","[[k|5]] MOAB Eliminator [[d|$25.000]]: Assassinate ability does 6x damage with a short cooldown."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Extra Range [[d|$200]]: Increases attack range.","[[k|2]] Frag Bombs [[d|$300]]: Explosions throw sharp fragments that can pop more Bloons including Black Bloons.","[[k|3]] Cluster Bombs [[d|$900]]: Throws out secondary bombs instead of sharp fragments every shot.","[[k|4]] Recursive Cluster [[d|$3.200]]: Every second shot the cluster bombs send out more cluster bombs for even more destruction.","[[k|5]] Bomb Blitz [[d|$38.000]]: Deals much more damage and, when lives are lost, the Bomb Storm automatically triggers, which destroys all but the biggest bloons."]}],"image":"https://static.wikia.nocookie.net/b__/images/b/b1/000-BombShooter.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"boomerang-monkey","name":"Boomerang Monkey","quote":"Hurls a boomerang that follows a curved path. Good range and pierce.","stats":[[["Fiyat","Cost"],"$325"],[["Hasar","Damage"],"1"],[["Delme","Pierce"],"4"],[["Saldırı hızı","Attack speed"],"Moderately Slow (every 1.2s)"],[["Menzil","Range"],"40"],[["Kamuflaj","Camo"],"Limited (except 5-x-x orbitals)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Improved Rangs [[d|$200]]: Can pop up to 7 Bloons per throw.","[[k|2]] Glaives [[d|$280]]: Throws sharper glaives instead of boomerangs.","[[k|3]] Glaive Ricochet [[d|$1.300]]: Glaives will bounce from Bloon to Bloon automatically and aggressively.","[[k|4]] M.O.A.R. Glaives [[d|$3.400]]: Multiple Object Advanced Ricochet greatly enhances the already extraordinary powers of the Glaive Ricochet Monkey.","[[k|5]] Glaive Lord [[d|$30.000]]: Glaive Lord surrounds itself in 3 special glaives that shred anything that comes near. Glaive Lord\u0027s glaives now rip through MOAB-class Bloons."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Faster Throwing [[d|$175]]: Throws boomerangs faster.","[[k|2]] Faster Rangs [[d|$250]]: Boomerangs fire and travel faster.","[[k|3]] Bionic Boomerang [[d|$1.100]]: Replaces arm with a strong bionic arm that can throw boomerangs extremely fast and does extra damage to MOAB-class Bloons.","[[k|4]] Turbo Charge [[d|$4.500]]: Turbo Charge Ability: Makes this Monkey attack incredibly fast for 8 seconds.","[[k|5]] Perma Charge [[d|$33.000]]: Perma Charge has a permanent super fast attack speed. Ability increases the lethality even more."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Long Range Rangs [[d|$100]]: Can throw boomerangs further than normal.","[[k|2]] Red Hot Rangs [[d|$300]]: Allows boomerangs to pop Frozen and Lead Bloons and do more damage to all.","[[k|3]] Kylie Boomerang [[d|$1.100]]: Throws heavy kylie boomerangs that follow a straight path instead of curved.","[[k|4]] MOAB Press [[d|$3.400]]: Heavy kylie boomerangs hits MOAB class Bloons multiple times per throw and sometimes knocks them back a short way along the path.","[[k|5]] MOAB Domination [[d|$52.000]]: Special knockback kylies trigger more often and do lots of extra damage."]}],"image":"https://static.wikia.nocookie.net/b__/images/0/03/000-BoomerangMonkey.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"dart-monkey","name":"Dart Monkey","quote":"Throws a single dart at nearby bloons. Short range and low pierce but cheap.","stats":[[["Fiyat","Cost"],"$150"],[["Hasar","Damage"],"1"],[["Delme","Pierce"],"2"],[["Saldırı hızı","Attack speed"],"Every 0.95s"],[["Menzil","Range"],"32"],[["Kamuflaj","Camo"],"Yes (x-x-2)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Sharp Shots [[d|$100]]: Can pop 1 extra Bloon per shot.","[[k|2]] Razor Sharp Shots [[d|$150]]: Can pop 3 more bloons per shot.","[[k|3]] Spike-O-Pult [[d|$450]]: Converts into a Spike-o-pult that hurls large spiked balls. Good range, but slower attack speed. Each ball can pop lots of Bloons.","[[k|4]] Juggernaut [[d|$1.800]]: Hurls a giant spiked ball that pops lead and excels at crushing Ceramic Bloons.","[[k|5]] Ultra-Juggernaut [[d|$13.500]]: Gigantic spiked ball splits twice into 6 Juggernaut balls for even more destructive power."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Quick Shots [[d|$100]]: Shoots 15% faster.","[[k|2]] Very Quick Shots [[d|$100]]: Shoots 33% faster!","[[k|3]] Triple Shot [[d|$400]]: Throws 3 darts at a time instead of 1.","[[k|4]] Super Monkey Fan Club [[d|$9.000]]: Super Monkey Fan Club Ability: Converts up to 10 nearby Dart Monkeys including himself into Super Monkeys for 12 seconds.","[[k|5]] Plasma Monkey Fan Club [[d|$45.000]]: Elite membership of this club grants the Dart Monkeys even more power!"]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Long Range Darts [[d|$90]]: Makes the Dart Monkey shoot further than normal.","[[k|2]] Enhanced Eyesight [[d|$200]]: Shoots even further and can detect Camo Bloons.","[[k|3]] Crossbow [[d|$600]]: Uses a long range Crossbow that can pop 3 layers of Bloon for every hit.","[[k|4]] Sharp Shooter [[d|$2.000]]: Sharp Shooter does powerful Crit Shots every few seconds that ricochet once and do a lot more damage.","[[k|5]] Crossbow Master [[d|$25.000]]: Crossbow Master shoots really fast and devastates most Bloon types with ease."]}],"image":"https://static.wikia.nocookie.net/b__/images/b/b2/000-DartMonkey.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"dartling-gunner","name":"Dartling Gunner","quote":"Uses a Dart-Shooting Machine-Gun. Aims wherever you last clicked on the screen.","stats":[[["Fiyat","Cost"],"$800"],[["Hasar","Damage"],"1"],[["Delme","Pierce"],"2"],[["Saldırı hızı","Attack speed"],"0.2s"],[["Menzil","Range"],"Infinite (dart attack) / 20 (\"display\" range)"],[["Kamuflaj","Camo"],"Yes (x-1-x)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Focused Firing [[d|$200]]: Increases accuracy of the Dartling Gun.","[[k|2]] Laser Shock [[d|$600]]: Laser tipped shots shock bloons into popping again 1 second after being struck.","[[k|3]] Laser Cannon [[d|$2.800]]: Rapidly fires much more powerful laser blasts that can pop lead \u0026 frozen bloons.","[[k|4]] Plasma Accelerator [[d|$12.000]]: Concentrates a powerful beam of energy to a single point.","[[k|5]] Ray of Doom [[d|$80.000]]: Creates a solid line of annihilation. You can erase most Bloons at your leisure."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Advanced Targeting [[d|$250]]: Allows Dartling Gunner to hit Camo Bloons.","[[k|2]] Faster Barrel Spin [[d|$500]]: Makes gun fire much faster.","[[k|3]] Hydra Rocket Pods [[d|$5.100]]: Shoots depleted bloontonium missiles that can damage all Bloon types and trigger multiple explosions.","[[k|4]] Rocket Storm [[d|$5.500]]: Rocket Storm ability: Launches a powerful storm of rockets in a wide cone.","[[k|5]] M.A.D [[d|$68.000]]: Moab Assured Destroyer. Slower firing mega missiles do extreme damage to MOAB-class Bloons."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Faster Swivel [[d|$100]]: Barrel can swivel much faster.","[[k|2]] Powerful Darts [[d|$800]]: Darts move faster, can pop more bloons each shot and can pop frozen bloons.","[[k|3]] Buckshot [[d|$3.400]]: Shoots blasts of deadly buckshot instead of darts.","[[k|4]] Bloon Area Denial System [[d|$16.000]]: 4-barreled auto-cannon that can be set to attack automatically.","[[k|5]] Bloon Exclusion Zone [[d|$50.000]]: Upgraded to 6 barrels and massively increased damage. Bloons are excluded from existence"]}],"image":"https://static.wikia.nocookie.net/b__/images/f/f3/000-DartlingGunner.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"druid","name":"Druid","quote":"Creates a blast of thorns for each attack. Upgrades can call forth powers of the Jungle, Storm, or Wrath.","stats":[[["Fiyat","Cost"],"$425"],[["Hasar","Damage"],"1 (spray of 5)"],[["Delme","Pierce"],"1 (spray of 5)"],[["Saldırı hızı","Attack speed"],"1.1s"],[["Menzil","Range"],"35"],[["Kamuflaj","Camo"],"Yes (5-x-x, x-5-x thorns)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Hard Thorns [[d|$250]]: Hard thorns can pop 2 bloons each and pop Lead and Frozen bloons.","[[k|2]] Heart of Thunder [[d|$1.000]]: Unleashes regular blasts of forked lightning that arc from bloon to bloon.","[[k|3]] Druid of the Storm [[d|$1.500]]: Gusts of wind blow Bloons off the track away from the exit.","[[k|4]] Ball Lightning [[d|$4.300]]: Makes powerful balls of lightning that shoot additional lightning bolts.","[[k|5]] Superstorm [[d|$55.000]]: Superstorm blasts all Bloon types for massive damage and blows them away from the exit."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Thorn Swarm [[d|$350]]: Shoots 8 thorns per shot instead of 5.","[[k|2]] Heart of Oak [[d|$250]]: Attacks convert Regrow Bloons into normal Bloons.","[[k|3]] Druid of the Jungle [[d|$450]]: Calls a vine from the ground to entangle and crush Bloons one at a time. Sometimes a vine will give cash when it pops a bloon.","[[k|4]] Jungle\u0027s Bounty [[d|$4.500]]: Jungle\u0027s Bounty Ability: Generates cash each use.","[[k|5]] Spirit of the Forest [[d|$35.000]]: Grows thorned vines along the path that deal constant damage and generates lives and money when the ability is activated."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Druidic Reach [[d|$100]]: Increases range by a large amount.","[[k|2]] Heart of Vengeance [[d|$400]]: Gains 20% attack speed and 1% for every life lost from the starting value after the upgrade. Maxes at 100% and diminishes if lives are restored.","[[k|3]] Druid of Wrath [[d|$750]]: Gains attack speed during the round as long as the Druid is popping Bloons.","[[k|4]] Poplust [[d|$2.500]]: Boosts attack speed and pierce for all Druids in the radius. Can stack up to 5 times on a single Druid.","[[k|5]] Avatar of Wrath [[d|$45.000]]: The more bloons there are, the more damage it does!"]}],"image":"https://static.wikia.nocookie.net/b__/images/4/47/000-Druid.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"engineer-monkey","name":"Engineer Monkey","quote":"Holds a trusty nail-gun to pop the Bloons. Can upgrade to create its own nail-shooting sentry turrets.","stats":[[["Fiyat","Cost"],"$400"],[["Hasar","Damage"],"1"],[["Delme","Pierce"],"3"],[["Saldırı hızı","Attack speed"],"Moderately Fast (every 0.7s)"],[["Menzil","Range"],"40"],[["Kamuflaj","Camo"],"Yes (x-3-x, only decamo via foam)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Sentry Gun [[d|$400]]: Creates temporary sentry guns and deploys them nearby.","[[k|2]] Faster Engineering [[d|$350]]: Increased efficiency allows the Engineer to produce sentries, bloon traps, and cleansing foam more often.","[[k|3]] Sprockets [[d|$500]]: Increases sentry gun and Engineer attack speed.","[[k|4]] Sentry Expert [[d|$2.800]]: Sentries deploy with different damage types based on your need.","[[k|5]] Sentry Champion [[d|$32.000]]: Creates super-powerful but highly unstable sentries."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Larger Service Area [[d|$250]]: Shoots further and deploys sentries in a much larger area.","[[k|2]] Deconstruction [[d|$350]]: Nail gun and Sentry shots do extra damage to MOAB class and Fortified Bloons.","[[k|3]] Cleansing Foam [[d|$800]]: Sprays foam that removes Camo and Regrow and pops Lead bloons.","[[k|4]] Overclock [[d|$13.500]]: Overclock Ability: Target another tower to supercharge its attack speed for a short time.","[[k|5]] Ultraboost [[d|$100.000]]: Ultra-Overclocked Monkeys gain a small but permanent boost every time they are overclocked."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Oversize Nails [[d|$450]]: Massivization allows nails to pop 8 Bloons at once, including frozen. Also increases Foam and Sentry effectiveness.","[[k|2]] Pin [[d|$200]]: Pins Bloons in place for a short time when struck.","[[k|3]] Double Gun [[d|$350]]: Two guns for twice the fun.","[[k|4]] Bloon Trap [[d|$3.600]]: Bloon trap captures Bloons until full. Tap to empty full trap for cash.","[[k|5]] XXXL Trap [[d|$54.000]]: Huge Bloon traps can trap some of the largest Bloons in them..."]}],"image":"https://static.wikia.nocookie.net/b__/images/9/98/000-EngineerMonkey.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"glue-gunner","name":"Glue Gunner","quote":"Shoots a blob of sticky glue that slows Bloons down by 50%","stats":[[["Fiyat","Cost"],"$100"],[["Hasar","Damage"],"0"],[["Delme","Pierce"],"1"],[["Saldırı hızı","Attack speed"],"Moderate (every 0.9s)"],[["Menzil","Range"],"40"],[["Kamuflaj","Camo"],"Yes (x-x-4)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Glue Soak [[d|$150]]: Glue soaks through all layers of Bloon.","[[k|2]] Corrosive Glue [[d|$300]]: Glued bloons pop one layer every few seconds.","[[k|3]] Bloon Dissolver [[d|$2.300]]: Extreme solvents melt two layers every second, plus extra damage to ceramic and MOAB class.","[[k|4]] Bloon Liquefier [[d|$4.500]]: Can glue one additional Bloon per shot and applies liquefying compounds that do 10 pops every second.","[[k|5]] The Bloon Solver [[d|$19.000]]: Bloons a problem? Here\u0027s the solution."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Bigger Globs [[d|$100]]: Can coat 2 Bloons per shot.","[[k|2]] Glue Splatter [[d|$700]]: Splatters glue across up to 10 Bloons per shot.","[[k|3]] Glue Hose [[d|$2.200]]: Shoots glue 3x as fast!","[[k|4]] Glue Strike [[d|$4.000]]: Glue Strike ability: Glues all Bloons on screen, Glued bloons take extra damage and lead bloons are weakened.","[[k|5]] Glue Storm [[d|$14.000]]: Glue Storm ability pelts the whole screen over 20 seconds with glue. Glued Bloons take extra damage while glued."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Stickier Glue [[d|$120]]: Makes glue effect last much longer.","[[k|2]] Stronger Glue [[d|$400]]: Slows down bloons even more.","[[k|3]] MOAB Glue [[d|$3.200]]: Improved glue formula allows it to stick to MOAB class Bloons.","[[k|4]] Relentless Glue [[d|$2.200]]: Glued bloons create a small splat when popped which stuns nearby bloons. Glue Gunner gains camo detection.","[[k|5]] Super Glue [[d|$28.000]]: Glue so strong it temporarily immobilizes all affected Bloons!"]}],"image":"https://static.wikia.nocookie.net/b__/images/3/37/000-GlueGunner.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"heli-pilot","name":"Heli Pilot","quote":"Hovers wherever you last tapped on screen. Shoots from twin heavy dart guns.","stats":[[["Fiyat","Cost"],"$800"],[["Hasar","Damage"],"1"],[["Delme","Pierce"],"3"],[["Saldırı hızı","Attack speed"],"Fast (every 0.5s)"],[["Menzil","Range"],"40"],[["Kamuflaj","Camo"],"Yes (x-2-x)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Quad Darts [[d|$600]]: Shoots 4 darts per volley instead of 2.","[[k|2]] Pursuit [[d|$250]]: A new targeting option enables Heli to seek and pursue the Bloons automatically.","[[k|3]] Razor Rotors [[d|$1.800]]: Razor rotor blades rip up Bloons on contact, including Lead and Frozen bloons.","[[k|4]] Apache Dartship [[d|$17.500]]: Adds a large missile array and powerful machine guns.","[[k|5]] Apache Prime [[d|$45.000]]: The Apache Prime leaves most bloons wishing they\u0027d never been inflated."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Bigger Jets [[d|$200]]: Powerful jets make Heli move much faster.","[[k|2]] IFR [[d|$350]]: Allows Heli Pilot to detect and shoot Camo Bloons.","[[k|3]] Downdraft [[d|$3.200]]: Blows bloons away from the Heli, back toward the entrance.","[[k|4]] Support Chinook [[d|$7.500]]: Abilities: Drops lives and cash crates, or can pick up and redeploy most Monkey types.","[[k|5]] Special Poperations [[d|$30.000]]: Adds another ability which deploys a powerful special Monkey Marine with machine gun. The crates are worth more cash and trigger all other crate drop abilities not on cooldown."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Faster Darts [[d|$350]]: Darts are propelled much faster through the air, allowing them to hit more bloons.","[[k|2]] Faster Firing [[d|$250]]: Faster attack speed for all Heli attacks.","[[k|3]] MOAB Shove [[d|$3.700]]: Can collide with and shove MOAB-Class Bloons, reversing or slowing their movement. Shove is amplified by Bigger Jets and IFR upgrades.","[[k|4]] Comanche Defense [[d|$7.500]]: Automatically calls in mini Comanches when they\u0027re most needed.","[[k|5]] Comanche Commander [[d|$35.000]]: Upgraded weapons. Also automatically calls in 3 more Comanches. Permanently."]}],"image":"https://static.wikia.nocookie.net/b__/images/1/17/000-HeliPilot.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"ice-monkey","name":"Ice Monkey","quote":"Pops and freezes nearby Bloons for a short time. Frozen Bloons are immune to sharp damage. Can\u0027t freeze White, Zebra, or Lead Bloons.","stats":[[["Fiyat","Cost"],"$450"],[["Hasar","Damage"],"1"],[["Delme","Pierce"],"40"],[["Menzil","Range"],"20"],[["Kamuflaj","Camo"],"Yes (2-x-x)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Permafrost [[d|$100]]: Bloons move slowly even after thawing out.","[[k|2]] Cold Snap [[d|$350]]: Can freeze and pop Lead and Camo Bloons.","[[k|3]] Ice Shards [[d|$1.800]]: Razor sharp shards fly out when Frozen Bloons pop.","[[k|4]] Embrittlement [[d|$2.700]]: Detects Camo Bloons and all Bloons including MOABs hit become brittle, taking extra damage for a short time and losing Camo and Regrow properties permanently.","[[k|5]] Super Brittle [[d|$34.000]]: Bloons take huge damage while frozen including MOAB class Bloons."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Enhanced Freeze [[d|$225]]: Attacks faster and freezes for longer.","[[k|2]] Deep Freeze [[d|$350]]: Freezes through 3 layers of bloon and freezes for even longer.","[[k|3]] Arctic Wind [[d|$2.900]]: Greatly increases pierce and gains a super cold aura that slows bloons and freezes water nearby.","[[k|4]] Snowstorm [[d|$3.000]]: Snowstorm Ability: Freezes ALL bloons on screen, and increases the attack speed of all Ice Monkeys.","[[k|5]] Absolute Zero [[d|$18.000]]: Ability freezes all bloons for longer."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Larger Radius [[d|$100]]: Larger freeze area.","[[k|2]] Re-Freeze [[d|$200]]: Can re-freeze Bloons that are already frozen.","[[k|3]] Cryo Cannon [[d|$1.300]]: Shoots freezing bombs at bloons over long range.","[[k|4]] Icicles [[d|$2.400]]: Frozen Bloons grow sharp icicles that can pop Bloons that touch them.","[[k|5]] Icicle Impale [[d|$32.000]]: Shoots huge icicle spikes that do huge damage to MOAB class bloons and freezes them."]}],"image":"https://static.wikia.nocookie.net/b__/images/d/dc/000-IceMonkey.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"monkey-ace","name":"Monkey Ace","quote":"Flies above the ground shooting volleys of high-pierce darts.","stats":[[["Fiyat","Cost"],"$700"],[["Hasar","Damage"],"1 (spray of 8)"],[["Delme","Pierce"],"5 (spray of 8)"],[["Saldırı hızı","Attack speed"],"1.5s"],[["Kamuflaj","Camo"],"Yes (x-2-x)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Rapid Fire [[d|$550]]: Shoots faster than normal.","[[k|2]] Lots More Darts [[d|$600]]: Shoots 12 darts at a time.","[[k|3]] Fighter Plane [[d|$1.000]]: Flies fast and launches anti-MOAB missiles.","[[k|4]] Operation: Dart Storm [[d|$3.000]]: Shoots 16 darts per volley, and twice as fast.","[[k|5]] Sky Shredder [[d|$40.000]]: The Bloons will wish they had never come."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Exploding Pineapple [[d|$200]]: Drops pineapples to the ground that explode violently after a few seconds. Ace\u0027s explosive attacks are improved.","[[k|2]] Spy Plane [[d|$350]]: Allows Monkey Ace to hit and deal additional damage to Camo bloons.","[[k|3]] Bomber Ace [[d|$900]]: Drops a line of bombs when crossing the Bloon track.","[[k|4]] Ground Zero [[d|$15.000]]: Increases effectiveness of bomb drops. Ground Zero Ability: drops a huge bomb that destroys most things on screen.","[[k|5]] Tsar Bomba [[d|$30.000]]: A very, very large bomb. Someone put a stop to craziness!"]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Sharper Darts [[d|$450]]: Darts can pop 9 Bloons each.","[[k|2]] Advanced Navigation [[d|$300]]: Adds finer control over the Ace\u0027s flight path for maximum map coverage.","[[k|3]] Neva-Miss Targeting [[d|$2.200]]: Darts automatically seek out and pop Bloons by themselves.","[[k|4]] Spectre [[d|$20.000]]: Rapidly fires darts and bombs, dominating most bloon types easily.","[[k|5]] Flying Fortress [[d|$75.000]]: This is a BIG plane."]}],"image":"https://static.wikia.nocookie.net/b__/images/b/b4/000-MonkeyAce.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"monkey-buccaneer","name":"Monkey Buccaneer","quote":"Shoots a single, heavy dart from both sides of the ship. Must be placed in water.","stats":[[["Fiyat","Cost"],"$500"],[["Hasar","Damage"],"1"],[["Delme","Pierce"],"4"],[["Saldırı hızı","Attack speed"],"1.0s"],[["Menzil","Range"],"60"],[["Kamuflaj","Camo"],"Yes (x-x-2)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Faster Shooting [[d|$350]]: All weapons on board shoot faster. Ability cooldowns are reduced.","[[k|2]] Double Shot [[d|$550]]: Double ship weapons fired.","[[k|3]] Destroyer [[d|$2.200]]: Attacks super duper fast!","[[k|4]] Aircraft Carrier [[d|$6.400]]: Launches waves of fighter planes that strafe their targets and fire missiles at MOAB class Bloons.","[[k|5]] Carrier Flagship [[d|$25.000]]: Does extra damage. Can place other Monkeys on the upper decks of the ship and increases attack speed of all water based Monkeys and Monkey Aces."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Grape Shot [[d|$550]]: Adds a spray of 5 sharpened grapes to the ship.","[[k|2]] Hot Shot [[d|$500]]: Burning hot grape shot can pop Lead Bloons and set Bloons on fire.","[[k|3]] Cannon Ship [[d|$900]]: Adds a powerful cannon that shoots out powerful bombs.","[[k|4]] Monkey Pirates [[d|$5.250]]: Adds 2 cannons to the ship and cannon attacks do more damage. MOAB Takedown Ability: harpoons a MOAB class Bloon and brings it down.","[[k|5]] Pirate Lord [[d|$21.000]]: Greatly increased attack speed for all attacks and can shoot 3 grappling hooks at once."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Long Range [[d|$300]]: Much longer range and projectiles fly faster.","[[k|2]] Crow\u0027s Nest [[d|$400]]: Allows the ship to hit, and deal extra damage to, Camo bloons.","[[k|3]] Merchantman [[d|$1.500]]: Generates cash each round automatically.","[[k|4]] Favored Trades [[d|$5.700]]: Attacks faster and generates lots of money per round. Monkeys in radius have increased sell value.","[[k|5]] Trade Empire [[d|$19.000]]: Generates more cash per round, increases cash earned by up to 20 other Merchantmen by the number of Merchantmen, and boosts all Merchantmen damage."]}],"image":"https://static.wikia.nocookie.net/b__/images/8/87/BTD6_Monkey_Buccaneer.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"monkey-sub","name":"Monkey Sub","quote":"Shoots homing torp-e-darts at nearby bloons. Must be placed in water.","stats":[[["Fiyat","Cost"],"$325"],[["Hasar","Damage"],"1"],[["Delme","Pierce"],"2"],[["Saldırı hızı","Attack speed"],"Moderately Fast (every 0.75s (?))"],[["Menzil","Range"],"40"],[["Kamuflaj","Camo"],"Yes (3-x-x, or 2-x-x if another camo tower)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Longer Range [[d|$130]]: Increases attack range.","[[k|2]] Advanced Intel [[d|$500]]: Allows long range targeting of Bloons in radius of your other towers.","[[k|3]] Submerge and Support [[d|$950]]: Adds Submerge targeting option that permanently reveals Camo bloons in its radius but does not attack while submerged.","[[k|4]] Bloontonium Reactor [[d|$2.800]]: Submerge to detect Camo, pop bloons and reduce ability cooldowns of nearby water-based Monkeys by 15%.","[[k|5]] Energizer [[d|$32.000]]: Reduces ability cooldowns everywhere by 20%. While in radius, Heroes earn XP 75% faster and water Monkeys\u0027 ability cooldowns are halved."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Barbed Darts [[d|$300]]: Sub\u0027s darts can pop an additional 3 bloons.","[[k|2]] Heat-tipped Darts [[d|$300]]: Heat tipped darts and a more powerful reactor allow popping of Frozen and Lead Bloons.","[[k|3]] Ballistic Missile [[d|$1.600]]: Missile seeks target within range and does extra MOAB and Ceramic damage.","[[k|4]] First Strike Capability [[d|$15.000]]: First Strike Ability: A devastating missile strike targeting the largest bloon on screen, plus splash damage.","[[k|5]] Pre-Emptive Strike [[d|$30.000]]: Automatically triggers an extra anti-MOAB missile whenever MOAB-Class Bloon spawns from the Bloon entrance."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Twin Guns [[d|$300]]: Added twin gun doubles attack speed. Enhances Ballistic Missile and Bloontonium Reactor.","[[k|2]] Airburst Darts [[d|$800]]: Airburst darts split into 3 on impact for massive popping power. Further enhances Ballistic Missile and Bloontonium Reactor.","[[k|3]] Triple Guns [[d|$800]]: Adds a third gun for even faster firing.","[[k|4]] Armor Piercing Darts [[d|$2.800]]: Special AP darts gain increased damage and popping power, plus additional damage to MOAB class Bloons.","[[k|5]] Sub Commander [[d|$25.000]]: Adds extra pierce and damage to Commander and all other Monkey Subs."]}],"image":"https://static.wikia.nocookie.net/b__/images/9/90/000-MonkeySub.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"monkey-village","name":"Monkey Village","quote":"Hub of Monkey industry, has a number of different benefits to aid all of your Monkeys. Increases range of all Monkeys in its radius by 10%.","stats":[[["Fiyat","Cost"],"$1.000"],[["Menzil","Range"],"40"],[["Kamuflaj","Camo"],"Yes (x-2-x)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Bigger Radius [[d|$400]]: Increases influence radius of the village.","[[k|2]] Jungle Drums [[d|$1.500]]: Increases attack speed of all Monkeys in the radius.","[[k|3]] Primary Training [[d|$800]]: All Primary Monkeys and Pat Fusty in radius get more range, pierce and projectile speed.","[[k|4]] Primary Mentoring [[d|$2.500]]: All Primary Monkeys in radius get tier 1 upgrades for free. Both they and Pat Fusty get increased range and reduced ability cooldowns.","[[k|5]] Primary Expertise [[d|$25.000]]: Adds Mega Ballista attack, plus all Primary Monkeys and Pat Fusty in radius get more popping power. Nearby Primary Monkeys also get tier 1 and 2 upgrades for free."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Grow Blocker [[d|$250]]: Prevents Regrow Bloons from working while in the radius of the Village.","[[k|2]] Radar Scanner [[d|$1.700]]: Allows all Monkeys in the radius to attack Camo Bloons.","[[k|3]] Monkey Intelligence Bureau [[d|$5.000]]: The Bureau grants special Bloon popping knowledge, allowing nearby Monkeys to pop all Bloon types.","[[k|4]] Call To Arms [[d|$23.500]]: Call to Arms ability: Gives nearby Monkeys +50% attack speed and pops for a short time.","[[k|5]] Homeland Defense [[d|$45.000]]: Ability now increases attack speed and pops by 100% for all Monkeys for 17 seconds."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Monkey Business [[d|$500]]: Provides 10% discount on all Monkeys and upgrades tier 3 or less purchased in the radius of the Village.","[[k|2]] Monkey Commerce [[d|$500]]: An additional 5% discount that can stack with up to 2 other Villages with this upgrade.","[[k|3]] Monkeyconomy [[d|$1.500]]: Generates crates of cash each round.","[[k|4]] Monkey City [[d|$7.200]]: Crates are worth more cash and range is increased.","[[k|5]] Monkeyopolis [[d|$150.005.000]]: Absorbs all Monkeyconomy and Monkey City villages and their benefits, freeing up space for more monkeys. Bloon sends are worth 20% more income."]}],"image":"https://static.wikia.nocookie.net/b__/images/8/8b/000-MonkeyVillage.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"mortar-monkey","name":"Mortar Monkey","quote":"Launches an exploding mortar shell to a fixed location anywhere on the screen.","stats":[[["Fiyat","Cost"],"$700"],[["Hasar","Damage"],"1"],[["Delme","Pierce"],"40"],[["Saldırı hızı","Attack speed"],"Slow (every 2.0s)"],[["Menzil","Range"],"Infinite (mortar projectile) / 30 (\"display\" range)"],[["Kamuflaj","Camo"],"Yes (x-x-3)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Bigger Blast [[d|$350]]: Bigger shells deliver a bigger blast radius.","[[k|2]] Bloon Buster [[d|$500]]: Smash through 2 layers of bloons at once!","[[k|3]] Shell Shock [[d|$1.300]]: Blast shockwave stuns bloons at impact, pops bloons in a wider area, and increases Burny Stuff damage.","[[k|4]] The Big One [[d|$7.300]]: Devastating explosions pop 7 layers of bloon, plus increases Burny Stuff damage further.","[[k|5]] The Biggest One [[d|$28.000]]: Stuns all but the biggest MOABs as it blasts deeply through Bloons and layers over a huge area, plus powerful Burny Stuff damage."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Faster Reload [[d|$400]]: Increases the attack speed of the Mortar.","[[k|2]] Rapid Reload [[d|$550]]: Even faster reload.","[[k|3]] Heavy Shells [[d|$800]]: Heavy shells do extra damage to Ceramic, Lead, all Fortified, and all stunned bloons. Can also pop Black bloons.","[[k|4]] Artillery Battery [[d|$8.000]]: Significantly faster reload and bonus BAD damage. Unlocks Bombardment Ability: 7 seconds of relentless destruction.","[[k|5]] Pop and Awe [[d|$27.000]]: Pop and Awe Ability: rains explosions over the whole screen, damaging and stunning all bloons. Main attack gains additional bonus damage to stunned Bloons. All Artillery Batteries do more damage to BADs."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Dynamic Targeting [[d|$400]]: Allows the mortar to aim itself at the single strongest bloon or the densest cluster of bloons.","[[k|2]] Burny Stuff [[d|$500]]: Damaged Bloons are set ablaze momentarily with each hit.","[[k|3]] Signal Flare [[d|$700]]: Camo Bloons popped by flares lose their camouflage permanently.","[[k|4]] Shattering Shells [[d|$8.500]]: Shattering shells strip all special bloon properties off all but the biggest bloons.","[[k|5]] Blooncineration [[d|$40.000]]: Superhot burny stuff melts through 5 layers of bloon each shot, burns MOAB class bloons for extra damage, and strips special properties from ZOMGs and DDTs."]}],"image":"https://static.wikia.nocookie.net/b__/images/8/8d/000-MortarMonkey.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"ninja-monkey","name":"Ninja Monkey","quote":"Stealthy and fast Monkey that throws bladed shurikens to pop the Bloons. Can target Camo Bloons.","stats":[[["Fiyat","Cost"],"$350"],[["Hasar","Damage"],"1"],[["Delme","Pierce"],"3"],[["Saldırı hızı","Attack speed"],"Moderately Fast (every 0.70s)"],[["Menzil","Range"],"40"],[["Kamuflaj","Camo"],"Yes (can decamo with x-2-x)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Ninja Discipline [[d|$150]]: Increases attack range and attack speed.","[[k|2]] Sharp Shurikens [[d|$200]]: Shurikens can pop 4 Bloons each.","[[k|3]] Double Shot [[d|$700]]: Throws 2 shurikens at once.","[[k|4]] Bloonjitsu [[d|$2.750]]: Throws 5 shurikens at once!","[[k|5]] Grandmaster Ninja [[d|$35.000]]: Throws incredibly fast, 8 shurikens per shot!"]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Distraction [[d|$200]]: Some Bloons will become distracted and move backwards.","[[k|2]] Counter-Espionage [[d|$375]]: Ninja attacks can strip camo from Bloons they hit.","[[k|3]] Shinobi Tactics [[d|$2.100]]: Increases attack speed and pierce of nearby Ninjas. Stacks 15 times.","[[k|4]] Bloon Sabotage [[d|$4.500]]: Sabotage Ability: Lasts 15 seconds. During the sabotage, all Bloons move at reduced speed.","[[k|5]] Grand Saboteur [[d|$20.000]]: Ability duration is longer, and MOAB bloon health is reduced during the sabotage. Shinobis in range get increased range and MOAB damage."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Seeking Shuriken [[d|$200]]: Shurikens will seek out and pop Bloons automatically.","[[k|2]] Caltrops [[d|$250]]: Throws out spiked caltrops onto the track nearby.","[[k|3]] Flash Bomb [[d|$1.800]]: Throws a flash bomb that stuns multiple Bloons.","[[k|4]] Sticky Bomb [[d|$4.900]]: Throws powerful timed charges at MOAB bloons.","[[k|5]] Master Bomber [[d|$40.000]]: One Monkey MOAB demolition machine."]}],"image":"https://static.wikia.nocookie.net/b__/images/2/28/000-NinjaMonkey.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"sniper-monkey","name":"Sniper Monkey","quote":"Can shoot Bloons it can see anywhere on the screen with a long-range rifle, and pops 2 layers off Bloons hit by it.","stats":[[["Fiyat","Cost"],"$300"],[["Hasar","Damage"],"2"],[["Delme","Pierce"],"1"],[["Saldırı hızı","Attack speed"],"1.59s"],[["Menzil","Range"],"Full Map (not behind objects)"],[["Kamuflaj","Camo"],"Yes (x-1-x)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Full Metal Jacket [[d|$250]]: Shots pop through 4 layers of bloon, and both bullets and shrapnel can pop Lead and Frozen Bloons.","[[k|2]] Large Calibre [[d|$750]]: Shots can pop through 7 layers of Bloon.","[[k|3]] Deadly Precision [[d|$2.800]]: 20 damage per shot, plus bonus damage to Ceramics.","[[k|4]] Maim MOAB [[d|$5.000]]: Immobilizes MOAB class bloons for a short time.","[[k|5]] Cripple MOAB [[d|$34.000]]: Crippled MOABs are immobilized for longer and take extra damage from all other attacks."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Night Vision Goggles [[d|$200]]: Allows Sniper to detect and do an additional 2 damage to Camo bloons.","[[k|2]] Shrapnel Shot [[d|$250]]: Damaged bloons spray out a cone of sharp shrapnel.","[[k|3]] Bouncing Bullet [[d|$3.000]]: Shots bounce to new targets up to 5 times.","[[k|4]] Supply Drop [[d|$5.800]]: Supply Drop ability: drops a crate full of cash. Regular attack also damages Lead Bloons and increases Shrapnel popping power.","[[k|5]] Elite Sniper [[d|$14.000]]: Supply Drop gives much more cash and activates Supply Drop for other snipers. Grants Elite targeting prio and faster reload to all snipers."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Fast Firing [[d|$300]]: Shoots faster than normal.","[[k|2]] Even Faster Firing [[d|$300]]: Shoots even faster!","[[k|3]] Semi-Automatic [[d|$2.200]]: Attacks 3x as fast!","[[k|4]] Full Auto Rifle [[d|$3.800]]: Fully automatic weapon with incredible popping power.","[[k|5]] Elite Defender [[d|$14.500]]: An escaping bloon or a lost life gives this Sniper 4x attack speed for a short time in retaliation. Also attacks faster the further the Bloons are along the track."]}],"image":"https://static.wikia.nocookie.net/b__/images/4/40/000-SniperMonkey.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"spike-factory","name":"Spike Factory","quote":"Automatically generates piles of Road Spikes on the nearby track. Excellent last line of defense.","stats":[[["Fiyat","Cost"],"$600"],[["Hasar","Damage"],"1"],[["Delme","Pierce"],"5"],[["Saldırı hızı","Attack speed"],"Moderately Slow (every 1.75s)"],[["Menzil","Range"],"34, 42 at x-x-1"],[["Kamuflaj","Camo"],"Yes"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Bigger Stacks [[d|$600]]: Creates larger piles of spikes per shot.","[[k|2]] White Hot Spikes [[d|$600]]: Cuts through Lead Bloons and Frozen Bloons.","[[k|3]] Spiked Balls [[d|$2.700]]: Produces spiked balls that do extra damage to Ceramic and Fortified bloons.","[[k|4]] Spiked Mines [[d|$9.500]]: Spiked mines explode violently when they lose all their spikes.","[[k|5]] Super Mines [[d|$90.000]]: Creates gigantic exploding spiked mines that can wipe out almost anything."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Faster Production [[d|$500]]: Rapidly increases production rate.","[[k|2]] Even Faster Production [[d|$500]]: Increases production rate even more.","[[k|3]] MOAB SHREDR [[d|$2.500]]: Super-Hard-Rending-Engine-Driven-Razors shred MOAB-Class Bloons.","[[k|4]] Spike Storm [[d|$6.200]]: Spike Storm ability: Shoots out a thick layer of spikes over the entire track.","[[k|5]] Carpet of Spikes [[d|$40.000]]: Regularly sets a carpet of spikes over the whole track."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Long Reach [[d|$150]]: Increases range for spike pile drops, plus piles last longer.","[[k|2]] Smart Spikes [[d|$500]]: Spike Factory gains special targeting priority and a small speed boost each round.","[[k|3]] Long Life Spikes [[d|$1.200]]: Spikes last much longer.","[[k|4]] Deadly Spikes [[d|$3.200]]: Extra deadly spikes can pop through 3 layers per spike and last even longer.","[[k|5]] Perma-Spike [[d|$30.000]]: High damage spikes become almost permanent."]}],"image":"https://static.wikia.nocookie.net/b__/images/f/f6/000-SpikeFactory.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"super-monkey","name":"Super Monkey","quote":"Throws hundreds of darts at hypersonic speeds with a huge attack range.","stats":[[["Fiyat","Cost"],"$2.000"],[["Hasar","Damage"],"1"],[["Delme","Pierce"],"1"],[["Saldırı hızı","Attack speed"],"0.045s"],[["Menzil","Range"],"50"],[["Kamuflaj","Camo"],"Yes (x-x-2)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Laser Blasts [[d|$1.400]]: Shoots powerful blasts of laser instead of darts","[[k|2]] Plasma Blasts [[d|$2.500]]: Super fast plasma melts through lead bloons.","[[k|3]] Sun Avatar [[d|$11.500]]: Channels power from the core of the Sun.","[[k|4]] Sun Temple [[d|$80.000]]: Tower sacrifices enhance and modify the Temple\u0027s attacks.","[[k|5]] True Sun God [[d|$200.000]]: Tremble before the AWESOME power of the TRUE Sun God!!"]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Super Range [[d|$1.000]]: Super Monkeys need Super Range.","[[k|2]] Epic Range [[d|$1.000]]: Why settle for super when you can have EPIC?","[[k|3]] Robo Monkey [[d|$10.000]]: Half Super Monkey, half killer robot of death. Shoots from 2 guns at once!","[[k|4]] Tech Terror [[d|$20.000]]: Annihilation ability: Destroys most Bloons completely and utterly within blast radius.","[[k|5]] The Anti-Bloon [[d|$90.000]]"]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Knockback [[d|$3.000]]: Bloons get pushed backwards or slowed after each hit.","[[k|2]] Ultravision [[d|$1.200]]: Enables Super Monkey to shoot slightly further and to see Camo Bloons.","[[k|3]] Dark Knight [[d|$4.500]]: Dark blades increase knockback and pierce and deal extra damage to MOAB class bloons. Gains Darkshift ability to shift to a nearby location.","[[k|4]] Dark Champion [[d|$32.000]]: Champion dark blades excel at puncturing and ruining all Bloon types. Darkshift ability extends mapwide.","[[k|5]] Legend of the Night [[d|$140.000]]: We turn to him, when all hope is lost..."]}],"image":"https://static.wikia.nocookie.net/b__/images/3/3d/000-SuperMonkey.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"tack-shooter","name":"Tack Shooter","quote":"Shoots a short-range volley of sharp tacks in 8 directions.","stats":[[["Fiyat","Cost"],"$280"],[["Hasar","Damage"],"1 (spray of 8)"],[["Delme","Pierce"],"1 (spray of 8)"],[["Saldırı hızı","Attack speed"],"Moderately Slow (every 1.4s)"],[["Menzil","Range"],"40"],[["Kamuflaj","Camo"],"Not at Base / (5-x-x meteor detects Camo)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Faster Shooting [[d|$150]]: Shoots tacks faster.","[[k|2]] Even Faster Shooting [[d|$400]]: Shoots tacks even faster.","[[k|3]] Hot Shots [[d|$700]]: Shoots superhot tacks that do extra damage and can pop Lead Bloons.","[[k|4]] Ring of Fire [[d|$3.500]]: Damages many more Bloons with a deadly ring of flame instead of tacks.","[[k|5]] Inferno Ring [[d|$45.500]]: Deadly inferno of flame roasts bloons into oblivion."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Long Range Tacks [[d|$100]]: Tacks fly out further than normal.","[[k|2]] Super Range Tacks [[d|$225]]: Even longer range tacks that can pop more Bloons.","[[k|3]] Blade Shooter [[d|$750]]: Switches tacks out for sharp blades that can pop up to 2 additional Bloons.","[[k|4]] Blade Maelstrom [[d|$3.000]]: Activated Ability: Covers the area in a storm of blades.","[[k|5]] Super Maelstrom [[d|$15.000]]: Even more powerful Maelstrom ability and lasts longer."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] More Tacks [[d|$100]]: Shoots 10 tacks instead of 8, plus increases Ring of Fire damage.","[[k|2]] Even More Tacks [[d|$100]]: Shoots out 12 tacks per shot and increases Ring of Fire damage further.","[[k|3]] Tack Sprayer [[d|$450]]: Sprays out 16 tacks per volley.","[[k|4]] Overdrive [[d|$3.400]]: Shoots incredibly fast.","[[k|5]] The Tack Zone [[d|$24.000]]: Many, many tacks."]}],"image":"https://static.wikia.nocookie.net/b__/images/7/71/000-TackShooter.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"},{"id":"wizard-monkey","name":"Wizard Monkey","quote":"Hurls magical bolts of energy at the Bloons. Can upgrade to a variety of powerful spells.","stats":[[["Fiyat","Cost"],"$250"],[["Hasar","Damage"],"1"],[["Delme","Pierce"],"3"],[["Saldırı hızı","Attack speed"],"Moderately Slow (every 1.1s)"],[["Menzil","Range"],"40"],[["Kamuflaj","Camo"],"Yes (x-x-2)"]],"lists":[{"title":["1. yol","Path 1"],"items":["[[k|1]] Guided Magic [[d|$100]]: Magic shots seek out the Bloons, even behind cover.","[[k|2]] Arcane Blast [[d|$250]]: Bigger more powerful magic blasts pop through 2 layers of bloon.","[[k|3]] Arcane Mastery [[d|$1.200]]: Faster attacks with increased range, damage, and lead popping power.","[[k|4]] Arcane Spike [[d|$9.000]]: Faster firing magic does huge damage to most Bloon types.","[[k|5]] Archmage [[d|$32.000]]: A true master of magical wizardry."]},{"title":["2. yol","Path 2"],"items":["[[k|1]] Fireball [[d|$300]]: Every few seconds casts an explosive fireball spell.","[[k|2]] Wall of Fire [[d|$1.000]]: Creates a super hot wall of fire across the track to roast the Bloons as they pass.","[[k|3]] Dragon\u0027s Breath [[d|$3.000]]: Spews endless flames at nearby Bloons and enhances Fireball and Wall of Fire.","[[k|4]] Summon Phoenix [[d|$4.000]]: Summon Phoenix ability: Powerful phoenix wreaks Bloon havoc for 20 seconds.","[[k|5]] Wizard Lord Phoenix [[d|$50.000]]: Wizard Lord becomes a master of the flame, turning into a super powerful Lava Phoenix for a short time."]},{"title":["3. yol","Path 3"],"items":["[[k|1]] Intense Magic [[d|$300]]: More powerful magic shots move faster and can pop more Bloons.","[[k|2]] Monkey Sense [[d|$300]]: Allows the Wizard to hit Camo Bloons.","[[k|3]] Shimmer [[d|$1.500]]: Gains a dark magic attack that periodically reveals location of all nearby Camo bloons permanently.","[[k|4]] Necromancer [[d|$2.600]]: Reanimate recently popped enemies as servants to destroy the Bloons.","[[k|5]] Prince of Darkness [[d|$24.000]]: Reanimate even more powerful Bloon servants to obliterate the enemy and enhances all other Necromancers."]}],"image":"https://static.wikia.nocookie.net/b__/images/9/99/000-WizardMonkey.png/revision/latest/scale-to-width-down/160?path-prefix=bloons"}]}],"links":[{"label":["Bloons TD 6","Bloons TD 6"],"href":"../btd6/"}],"footer":[["Babuşlar, Ninja Kiwi ile bağlantılı değildir. Bloons TD Battles 2 ve görselleri Ninja Kiwi\u0027ye aittir.","Babuşlar is not affiliated with Ninja Kiwi. Bloons TD Battles 2 and its images belong to Ninja Kiwi."],["Veriler ve görseller Bloons Wiki\u0027den (bloons.fandom.com, CC BY-SA) alınır. Kule ve yükseltme adları İngilizcedir.","Data and images come from the Bloons Wiki (bloons.fandom.com, CC BY-SA)."]]};
